  "onboarding.tour.import.button.body": "PDF、EPUB、ウェブ記事、YouTube 動画、ポッドキャスト — すべてここに集まります。「インポート」をクリックしてファイルを開くか、リンク付きのコンテンツにはツールバーの URL インポートをご利用ください。",
  "onboarding.tour.import.button.title": "ドキュメントを取り込む",
  "onboarding.tour.import.grid.body": "インポートしたドキュメントはここに表示されます。どれかを開いて、読書と抽出の作成を始めましょう。",
  "onboarding.tour.import.grid.title": "あなたのライブラリ",
  "onboarding.tour.import.url.body": "ツールバーの「URL をインポート」で、ウェブ記事、arXiv 論文、YouTube トランスクリプトを取り込めます。コマンドパレット（Ctrl+K / Cmd+K）を使えばキーボードから離れずに同じ操作ができます。",
  "onboarding.tour.import.url.title": "URL からインポート",
  "onboarding.tour.knowledge.analytics.body": "定着率、復習アクティビティ、経時的な進捗を確認できます。復習するたびに数値が更新されます。",
  "onboarding.tour.knowledge.analytics.title": "統計",
  "onboarding.tour.knowledge.sphere.body": "ドキュメントと抽出の関連性を空間的にマップしたものです。ズームアウトして、学んだこと全体の形を確認しましょう。",
  "onboarding.tour.knowledge.sphere.title": "ナレッジユニバース",
  "onboarding.tour.make.settings.body": "設定には、テーマ、キーボードショートカット、同期、統合、AI プロバイダー、学習アルゴリズムが含まれます。アプリをカスタマイズするものはすべてここにあります。",
  "onboarding.tour.make.settings.title": "自分好みに",
  "onboarding.tour.make.workspace.body": "ワークスペースはライブラリを別々のコンテキスト（研究、個人、サイドプロジェクトなど）に分割します。ツールバーから切り替えられます。",
  "onboarding.tour.make.workspace.title": "ワークスペース",
  "onboarding.tour.next": "次へ",
  "onboarding.tour.queue.controls.body": "最適な復習セッションを開始し、読書・スケジュール・復習の各モードにキューを切り替えたり、手動で閲覧したりできます。キューは毎日のループを駆動する中心的な場所です。",
  "onboarding.tour.queue.controls.title": "キューコントロール",
  "onboarding.tour.queue.nav.body": "キューには追加したものすべて（読むドキュメント、学ぶ抽出）が保持されます。ナビから開いて、次の期限を確認したり、ランダムに選んだりできます。",
  "onboarding.tour.queue.nav.title": "キュー",
  "onboarding.tour.read.extract.body": "リーダーで文章を選択して、抽出として切り出します — メモ、フラッシュカード、穴埋めのいずれかです。抽出は復習スケジューラが学習する単位になります。",
  "onboarding.tour.read.extract.title": "抽出を作成",
  "onboarding.tour.read.extracts.body": "作成した抽出はすべてここに集まり、出典に紐付けられるため、いつでも元のコンテキストに戻れます。",
  "onboarding.tour.read.extracts.title": "抽出パネル",
  "onboarding.tour.read.reader.body": "各ドキュメントは長文読書向けに調整されたリーダーで専用タブに開きます。同じ画面に次に紹介する抽出ツールも用意されています。",
  "onboarding.tour.read.reader.title": "ビューアーで読む",
  "onboarding.tour.replayTour": "ガイドツアーをもう一度見る",
  "onboarding.tour.resetOnboarding": "オンボーディングをリセット",
  "onboarding.tour.resetOnboardingDesc": "起動回数、完了フラグ、再開位置をクリアします。新規インストール時と同様に、次回起動時にツアーが自動で開きます。",
  "onboarding.tour.review.algorithm.body": "Plethora は複数のスケジューラ（FSRS-6、Plethora Adaptive、Plethora Precision、Plethora Classic）を同梱しています。設定 → 学習で、あなたに合ったものを選んでください。",
  "onboarding.tour.review.algorithm.title": "アルゴリズムを選ぶ",
  "onboarding.tour.review.grading.body": "各カードの後に、想起に合った評価を選んでください。スケジューラはそのシグナルを使って次の表示時期を決定します — 想起が良ければ、間隔は長くなります。",
  "onboarding.tour.review.grading.title": "評価コントロール",
  "onboarding.tour.review.nav.body": "抽出の期限が来ると、復習セッションが各抽出を順に提示し、どれくらい覚えていたかを尋ねます。あなたの回答が間隔反復スケジューラを学習させます。",
  "onboarding.tour.review.nav.title": "復習セッション",
  "onboarding.tour.skip": "ツアーをスキップ",
